  /// Returns the [KinshipEdgeCategory] for [relationshipKey].
  ///
  /// Looks up the key in the pre-built map. If the key is not found
  /// (e.g. a custom/synthetic key like 'related', 'unknown'), returns
  /// [KinshipEdgeCategory.extended] as the safe fallback.
  ///
  /// This NEVER returns null and NEVER produces grey for any of the
  /// 5,363 known kinship keys.
  static KinshipEdgeCategory categoryFor(String? relationshipKey) {
    if (relationshipKey == null || relationshipKey.isEmpty) {
      return KinshipEdgeCategory.extended;
    }
    return _kinshipKeyToCategory[relationshipKey] ??
        KinshipEdgeCategory.extended;
  }

  /// Returns true if [relationshipKey] is in the mapping (i.e. is one
  /// of the 5,363 known kinship terms).
  static bool isKnown(String? relationshipKey) {
    if (relationshipKey == null || relationshipKey.isEmpty) return false;
    return _kinshipKeyToCategory.containsKey(relationshipKey);
  }

  /// Returns the total number of mapped keys.
  static int get size => _kinshipKeyToCategory.length;
}
